/** Hugeicons' own stroke, and the bolder one that marks a selected tab. */
private const val LINE = 1.5f
private const val BOLD = 2.25f
private const val CARET = 2f

private fun line(name: String, vararg paths: String, autoMirror: Boolean = false) = hugeicon(name, paths, LINE, false, autoMirror)

private fun bold(name: String, vararg paths: String) = hugeicon(name, paths, BOLD, false, false)

/** The outline filled in, for shapes that read as solid (play, pause, stop, the caret triangles). */
private fun solid(name: String, vararg paths: String) = hugeicon(name, paths, LINE, true, false)

/**
 * Strokes each path at [width] with round caps and joins on Hugeicons' 24 grid, filling it too when [filled].
 * Circles arrive already turned into arcs. [autoMirror] flips the icon in right-to-left layouts (arrows and carets).
 */
private fun hugeicon(name: String, paths: Array<out String>, width: Float, filled: Boolean, autoMirror: Boolean): ImageVector =
    ImageVector.Builder("Hugeicons.$name", 24.dp, 24.dp, viewportWidth = 24f, viewportHeight = 24f, autoMirror = autoMirror).apply {
        for (d in paths) addPath(
            PathParser().parsePathString(d).toNodes(),
            fill = if (filled) SolidColor(Color.Black) else null,
            stroke = SolidColor(Color.Black), strokeLineWidth = width,
            strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
        )
    }.build()
